import { ColDef, ColGroupDef } from 'ag-grid-community';
import classNames from 'classnames';

import ExecutionStatusCellRenderer from '@/src/components/Grid/CellRenderers/ExecutionStatusCellRenderer';
import ScoreCellRenderer from '@/src/components/Grid/CellRenderers/ScoreCellRenderer';
import {
  DURATION_COLUMN_WIDTH,
  EXTRACTED_COLUMN_MIN_WIDTH,
  fixedWidthColDef,
  HTTP_COLUMN_WIDTH,
  lockedWidthColDef,
  METRIC_COLUMN_WIDTH,
  NO_FILTER_COL_DEF,
  NUMBER_FILTER_COL_DEF,
  REQUEST_INDEX_COLUMN_WIDTH,
  RUN_INDEX_COLUMN_WIDTH,
  STATUS_COLUMN_WIDTH,
  TEST_CASE_NAME_COLUMN_WIDTH,
  TEXT_FILTER_COL_DEF,
  TOTAL_REQUESTS_COLUMN_WIDTH,
  TOTAL_TURNS_COLUMN_WIDTH,
  TURN_INDEX_COLUMN_WIDTH,
} from '@/src/components/Runs/grid-column-layout';
import {
  EXECUTION_GROUP_HEADER,
  EXTRACTED_GROUP_HEADER,
} from '@/src/components/Runs/Compare/ExecutionResults/constants';
import { RowDetailFieldSchema } from '@/src/components/Runs/Details/RowDetails/models';
import { NO_BORDER_CLASS } from '@/src/constants/ag-grid';
import { rightAlignedColumn } from '@/src/constants/grid-columns/configs';
import { MetricBindings, MetricSnapshot } from '@/src/models/evaluation/metric';
import { AnalyticsResult, ExtractionResult, Run } from '@/src/models/evaluation/run';
import { FilterDto } from '@/src/models/request';
import { FilterOperatorDto } from '@/src/types/request';
import { getUniformExecutionFields, hideUniformColumns } from '@/src/utils/evaluation/column-variation';

import { CompareAnalyticsRow, MetricGroup } from './models';
import EllipsisHeader from '@/src/components/Grid/HeaderComponents/EllipsisHeader';
import EllipsisHeaderGroup from '@/src/components/Grid/HeaderComponents/EllipsisHeaderGroup';
export type { MetricGroup } from './models';

export const RUN_FILTER = (id?: string | null): FilterDto[] => [
  { column: 'runId', operator: FilterOperatorDto.EQUALS, value: id || '' },
];

export const RESULT_FILTERS = (run: Run): FilterDto[] => [
  ...RUN_FILTER(run.id),
  {
    column: 'suiteId',
    operator: FilterOperatorDto.EQUALS,
    value: run.testSuiteId || '',
  },
];

const ELLIPSIS_HEADER_PARAMS = { innerHeaderComponent: EllipsisHeader };
const RIGHT_ALIGNED_ELLIPSIS_HEADER_PARAMS = {
  innerHeaderComponent: EllipsisHeader,
  innerHeaderComponentParams: { isRightAligned: true },
};

const getInputColumns = (input: Record<string, unknown>, hide = false) => {
  return Object.keys(input).map((key) => {
    return {
      field: key,
      headerName: key,
      headerComponentParams: ELLIPSIS_HEADER_PARAMS,
      hide,
      flex: 1,
      minWidth: EXTRACTED_COLUMN_MIN_WIDTH,
      ...NO_FILTER_COL_DEF,
      valueGetter: (params) => {
        const value = params.data?.testCaseData?.[key];
        if (value == null) return '—';
        if (typeof value === 'object') return JSON.stringify(value);
        return value;
      },
    } as ColDef;
  });
};

const getExtractedColumns = (extracted: Record<string, unknown>) => {
  return Object.keys(extracted).map((key) => {
    return {
      field: key,
      headerName: key,
      headerComponentParams: ELLIPSIS_HEADER_PARAMS,
      flex: 1,
      minWidth: EXTRACTED_COLUMN_MIN_WIDTH,
      ...NO_FILTER_COL_DEF,
      valueGetter: (params) => {
        const value = params.data?.extractedColumns?.[key];
        if (value == null) return '—';
        if (typeof value === 'object') return JSON.stringify(value);
        return value;
      },
    } as ColDef;
  });
};

const mergeMetricValuesSchema = (results: AnalyticsResult[]): Record<string, Record<string, unknown>> => {
  const merged: Record<string, Record<string, unknown>> = {};
  for (const result of results) {
    const mv = result.metricValues;
    if (!mv) continue;
    for (const [groupKey, groupValues] of Object.entries(mv)) {
      if (!merged[groupKey]) merged[groupKey] = {};
      for (const [key, val] of Object.entries(groupValues)) {
        if (!(key in merged[groupKey])) merged[groupKey][key] = val;
      }
    }
  }
  return merged;
};

/** Numbers line up on the right under their header; any other value keeps the text layout. */
const metricAlignment = (sample: unknown): Partial<ColDef> =>
  typeof sample === 'number'
    ? { ...rightAlignedColumn, headerComponentParams: RIGHT_ALIGNED_ELLIPSIS_HEADER_PARAMS }
    : { headerComponentParams: ELLIPSIS_HEADER_PARAMS };

const getMetricsColumns = (metrics: Record<string, Record<string, unknown>>) => {
  return Object.entries(metrics).map(([groupKey, groupValues]) => ({
    headerName: groupKey,
    headerGroupComponent: EllipsisHeaderGroup,
    children: Object.entries(groupValues).map(
      ([key, sample]) =>
        ({
          field: `${groupKey}_${key}`,
          colId: `${groupKey}_${key}`,
          headerName: key,
          cellRenderer: ScoreCellRenderer,
          ...NUMBER_FILTER_COL_DEF,
          ...fixedWidthColDef(METRIC_COLUMN_WIDTH),
          ...metricAlignment(sample),
          cellClass: ['p-0', NO_BORDER_CLASS],
          valueGetter: (params) => {
            const groupExists = params.data?.metricValues != null && groupKey in params.data.metricValues;
            if (!groupExists) return '—';
            const value = params.data?.metricValues?.[groupKey]?.[key];
            if (value == null) return '—';
            if (typeof value === 'object') return JSON.stringify(value);
            return +value.toFixed(3);
          },
          comparator(valueA, valueB, nodeA, nodeB, isDescending) {
            const metricA = nodeA?.data?.metricValues?.[groupKey]?.[key];
            const metricB = nodeB?.data?.metricValues?.[groupKey]?.[key];

            const isErrorA = metricA == null;
            const isErrorB = metricB == null;

            if (isErrorA && isErrorB) return 0;
            if (isErrorA) return isDescending ? -1 : 1;
            if (isErrorB) return isDescending ? 1 : -1;

            if (typeof metricA === 'number' && typeof metricB === 'number') {
              if (metricA === metricB) return 0;
              return metricA > metricB ? 1 : -1;
            }

            const normalizedA = typeof valueA === 'string' ? valueA : String(valueA);
            const normalizedB = typeof valueB === 'string' ? valueB : String(valueB);

            return normalizedA.localeCompare(normalizedB);
          },
        }) as ColDef,
    ),
  }));
};

type IndexColumnField = 'runIndex' | 'requestIndex' | 'turnIndex';

const buildIndexColumn = (field: IndexColumnField, headerName: string, width: number): ColDef => ({
  field,
  headerName,
  headerComponentParams: RIGHT_ALIGNED_ELLIPSIS_HEADER_PARAMS,
  colId: field,
  sortable: true,
  ...lockedWidthColDef(width),
  ...NO_FILTER_COL_DEF,
  ...rightAlignedColumn,
  valueGetter: (params) => (params.data?.[field] != null ? params.data[field] + 1 : null),
});

const executionColumns: ColDef[] = [
  buildIndexColumn('runIndex', '# Run number', RUN_INDEX_COLUMN_WIDTH),
  buildIndexColumn('requestIndex', 'Request', REQUEST_INDEX_COLUMN_WIDTH),
  {
    field: 'totalRequests',
    headerName: 'Total requests',
    headerComponent: EllipsisHeader,
    headerComponentParams: { isRightAligned: true },
    colId: 'totalRequests',
    hide: true,
    ...lockedWidthColDef(TOTAL_REQUESTS_COLUMN_WIDTH),
    ...NO_FILTER_COL_DEF,
    ...rightAlignedColumn,
    valueGetter: (params) => params.data?.totalRequests ?? null,
  },
  buildIndexColumn('turnIndex', 'Turn', TURN_INDEX_COLUMN_WIDTH),
  {
    field: 'totalTurns',
    headerName: 'Total turns',
    colId: 'totalTurns',
    hide: true,
    ...lockedWidthColDef(TOTAL_TURNS_COLUMN_WIDTH),
    ...NO_FILTER_COL_DEF,
    ...rightAlignedColumn,
    valueGetter: (params) => params.data?.totalTurns ?? null,
  },
  {
    field: 'responseStatusCode',
    headerName: 'HTTP',
    colId: 'http',
    ...lockedWidthColDef(HTTP_COLUMN_WIDTH),
    ...NO_FILTER_COL_DEF,
    ...rightAlignedColumn,
    // Replaces the spread's cellClass: the status tint is added on top of `align-right`.
    cellClass: (params) => classNames('align-right', getTestCaseStatusClass(params.data?.responseStatusCode)),
  },
  {
    field: 'durationMs',
    headerName: 'Duration',
    colId: 'duration',
    ...lockedWidthColDef(DURATION_COLUMN_WIDTH),
    ...NO_FILTER_COL_DEF,
    ...rightAlignedColumn,
    valueGetter: (params) => params.data?.executionInfo?.durationMs ?? params.data?.execDurationMs ?? null,
    valueFormatter: (params) => getFormattedDuration(params.value ?? undefined),
    // Replaces the spread's cellClass: the status tint is added on top of `align-right`.
    cellClass: (params) => classNames('align-right', getTestCaseStatusClass(params.data?.responseStatusCode)),
  },
];

const detailsColumns = {
  headerName: ' ',
  context: { panelName: 'Details' },
  children: [
    {
      field: 'executionStatus',
      headerName: ' ',
      context: { panelName: 'Status' },
      colId: 'status',
      ...lockedWidthColDef(STATUS_COLUMN_WIDTH),
      ...NO_FILTER_COL_DEF,
      cellRenderer: ExecutionStatusCellRenderer,
    },
    {
      field: 'testCaseName',
      headerName: 'Test Case name',
      colId: 'testCaseName',
      ...fixedWidthColDef(TEST_CASE_NAME_COLUMN_WIDTH),
      ...TEXT_FILTER_COL_DEF,
    },
  ],
};

/**
 * `Total requests` and `Total turns` ship hidden from `executionColumns`: a denominator is context for a
 * position rather than a reading of its own. Of what is left, an index column that reads the same on
 * every row distinguishes no result from another, so it too starts hidden and the operator re-enables it
 * from the columns panel.
 */
const getExecutionGroup = (results: AnalyticsResult[]) => ({
  headerName: EXECUTION_GROUP_HEADER,
  children: hideUniformColumns(executionColumns, getUniformExecutionFields(results)),
});

/**
 * A single row only carries the columns of the request that produced it, so a request chain spreads
 * its extracted columns and input bindings across rows — the union is the run's real schema.
 */
const mergeRecordSchema = (
  results: AnalyticsResult[],
  getRecord: (result: AnalyticsResult) => Record<string, unknown> | undefined,
): Record<string, unknown> =>
  results.reduce<Record<string, unknown>>((acc, result) => ({ ...acc, ...(getRecord(result) || {}) }), {});

const INPUT_BINDINGS_GROUP_HEADER = 'INPUT BINDINGS';

const NON_METRIC_GROUP_HEADERS = new Set([
  ' ',
  EXECUTION_GROUP_HEADER,
  EXTRACTED_GROUP_HEADER,
  INPUT_BINDINGS_GROUP_HEADER,
]);

/** Metric column-group headers in Extraction Result / Compare grid order. */
export const getMetricGroupOrder = (colDefs: (ColDef | ColGroupDef)[]): string[] =>
  colDefs
    .filter((col) => {
      const children = 'children' in col && col.children ? (col.children as ColDef[]) : [];
      return children.length > 0 && !!col.headerName && !NON_METRIC_GROUP_HEADERS.has(col.headerName);
    })
    .map((col) => col.headerName as string);

export const getRowDetailFieldSchema = (results: AnalyticsResult[]): RowDetailFieldSchema => ({
  metricValues: mergeMetricValuesSchema(results),
  testCaseData: mergeRecordSchema(results, (result) => result.testCaseData),
  extractedColumns: mergeRecordSchema(results, (result) => result.extractedColumns),
});

export const getAnalyticsColumns = (results: AnalyticsResult[]) => {
  const metrics = mergeMetricValuesSchema(results);
  const input = mergeRecordSchema(results, (result) => result.testCaseData);

  return [
    detailsColumns,
    getExecutionGroup(results),
    ...getMetricsColumns(metrics),
    {
      headerName: INPUT_BINDINGS_GROUP_HEADER,
      children: getInputColumns(input, true),
    },
    {
      headerName: EXTRACTED_GROUP_HEADER,
      children: getExtractedColumns(mergeRecordSchema(results, (result) => result.extractedColumns)),
    },
  ];
};

const getCompareChainSuffix = (row: AnalyticsResult): string => `${row.requestIndex ?? 0}::${row.turnIndex ?? 0}`;

const getCompareIdKey = (row: AnalyticsResult): string | null =>
  row.testCaseId ? `${row.testCaseId}::${row.runIndex}::${getCompareChainSuffix(row)}` : null;

const getCompareNameKey = (row: AnalyticsResult): string | null =>
  row.testCaseName ? `${row.testCaseName}::${row.runIndex}::${getCompareChainSuffix(row)}` : null;

export const createEmptyComparePrimaryRow = (
  source: Pick<
    AnalyticsResult,
    'testCaseId' | 'testCaseName' | 'runIndex' | 'requestIndex' | 'totalRequests' | 'turnIndex' | 'totalTurns'
  >,
): AnalyticsResult => ({
  testCaseId: source.testCaseId,
  testCaseName: source.testCaseName,
  runIndex: source.runIndex,
  requestIndex: source.requestIndex,
  totalRequests: source.totalRequests,
  turnIndex: source.turnIndex,
  totalTurns: source.totalTurns,
  responseStatusCode: undefined as unknown as number,
});

export const getCompareRowSelectionId = (row: CompareAnalyticsRow): string | null =>
  row.id ?? row._compared?.id ?? null;

export const isMatchedCompareRow = (row: CompareAnalyticsRow): boolean => Boolean(row.id && row._compared?.id);

const createComparedOnlyRow = (compared: AnalyticsResult): CompareAnalyticsRow => ({
  ...createEmptyComparePrimaryRow(compared),
  _compared: compared,
});

const sortCompareRows = (rows: CompareAnalyticsRow[]): CompareAnalyticsRow[] =>
  [...rows].sort((a, b) => {
    const nameCompare = (a.testCaseName ?? '').localeCompare(b.testCaseName ?? '');
    if (nameCompare !== 0) return nameCompare;
    if (a.runIndex !== b.runIndex) return a.runIndex - b.runIndex;
    const requestCompare = (a.requestIndex ?? 0) - (b.requestIndex ?? 0);
    if (requestCompare !== 0) return requestCompare;
    return (a.turnIndex ?? 0) - (b.turnIndex ?? 0);
  });

const indexRowsByKey = (
  rows: AnalyticsResult[],
  getKey: (row: AnalyticsResult) => string | null,
  exclude?: Set<AnalyticsResult>,
): Map<string, AnalyticsResult> => {
  const map = new Map<string, AnalyticsResult>();
  for (const row of rows) {
    if (exclude?.has(row)) continue;
    const key = getKey(row);
    if (key) map.set(key, row);
  }
  return map;
};

export const mergeByTestCaseId = (current: AnalyticsResult[], compared: AnalyticsResult[]): CompareAnalyticsRow[] => {
  const usedCompared = new Set<AnalyticsResult>();
  const merged: CompareAnalyticsRow[] = [];
  const unmatchedCurrent: AnalyticsResult[] = [];

  // Phase 1: match by testCaseId + runIndex + requestIndex + turnIndex when both sides share the same id
  const comparedById = indexRowsByKey(compared, getCompareIdKey);
  for (const row of current) {
    const idKey = getCompareIdKey(row);
    const match = idKey ? comparedById.get(idKey) : undefined;
    if (match) {
      merged.push({ ...row, _compared: match });
      usedCompared.add(match);
    } else {
      unmatchedCurrent.push(row);
    }
  }

  // Phase 2: match remaining rows by testCaseName + runIndex + requestIndex + turnIndex (e.g. public vs detached private copy)
  const comparedByName = indexRowsByKey(compared, getCompareNameKey, usedCompared);
  for (const row of unmatchedCurrent) {
    const nameKey = getCompareNameKey(row);
    const match = nameKey ? comparedByName.get(nameKey) : undefined;
    if (match && nameKey) {
      merged.push({ ...row, _compared: match });
      usedCompared.add(match);
      comparedByName.delete(nameKey);
    } else {
      merged.push({ ...row, _compared: null });
    }
  }

  for (const row of compared) {
    if (!usedCompared.has(row)) {
      merged.push(createComparedOnlyRow(row));
    }
  }

  return sortCompareRows(merged);
};

export const getTestCaseStatusClass = (code: number | undefined) => {
  if (code == null) return '';
  if (code >= 200 && code < 300) return 'text-success';
  if (code >= 400 && code < 500) return 'text-warning';
  return 'text-error';
};

export const getFormattedDuration = (durationMs: number | undefined) => {
  if (durationMs == null) return '—';
  if (durationMs >= 1000) return `${(durationMs / 1000).toFixed(1)}s`;
  return `${durationMs}ms`;
};

export const getPanelTitle = (result: ExtractionResult | AnalyticsResult | null) => {
  return `${result?.testCaseName} - Run #${(result?.runIndex ?? 0) + 1}`;
};

export const getDetailEntries = (data: Record<string, unknown>): Array<[string, unknown]> => {
  return Object.keys(data).map((key) => {
    const val = data[key];
    if (typeof val === 'string') return [key, val];
    if (typeof val === 'number' || typeof val === 'boolean' || typeof val === 'bigint') {
      return [key, String(val)];
    }
    if (val == null) return [key, String(val)];
    return [key, val];
  });
};

export const getMetricGroups = (
  metricValues?: Record<string, Record<string, unknown>>,
  metricInfos?: Record<string, Record<string, unknown>>,
): MetricGroup[] => {
  if (!metricValues) return [];

  return Object.entries(metricValues).map(([groupKey, values]) => {
    const infoGroup = metricInfos?.[groupKey];
    const hasOnlyNullError = Object.keys(values).length === 1 && 'error' in values && values.error == null;
    const infoError = infoGroup?.error;
    const hasError = (hasOnlyNullError && !!infoError) || Object.values(values).every((v) => v == null);

    const metrics = Object.entries(values)
      .filter(([key]) => key !== 'error' || !hasOnlyNullError)
      .map(([key, val]) => ({
        key,
        value: typeof val === 'number' ? val : null,
        isError: val == null,
      }));

    const infos = infoGroup
      ? Object.fromEntries(Object.entries(infoGroup).filter(([key]) => key !== 'error' || !hasError))
      : undefined;

    return {
      title: groupKey,
      metrics,
      info: infos && Object.keys(infos).length > 0 ? infos : undefined,
      hasError,
      errorMessage: hasError && infoError ? String(infoError) : undefined,
    };
  });
};

export const snapshotsToBindingsMap = (snapshots: MetricSnapshot[]): Record<string, MetricBindings> => {
  return snapshots.reduce(
    (acc, snapshot) => {
      if (snapshot.tsmdName) {
        acc[snapshot.tsmdName] = {
          configBindings: snapshot.configBindings ?? [],
          inputBindings: snapshot.inputBindings ?? [],
        };
      }
      return acc;
    },
    {} as Record<string, MetricBindings>,
  );
};

export const getDetailNestedEntries = (
  data: Record<string, Record<string, unknown>>,
  additionalData?: Record<string, Record<string, unknown>>,
): { title: string; entries: [string, string][] }[] => {
  return Object.entries(data).map(([groupKey, values]) => {
    const hasOnlyNullError = Object.keys(values).length === 1 && 'error' in values && values.error == null;
    const additionalGroup = additionalData?.[groupKey];
    const infoError = additionalGroup?.error;

    let entries: Array<[string, string]>;

    if (hasOnlyNullError && infoError) {
      entries = [['error', String(infoError)]];
    } else {
      entries = Object.entries(values).flatMap(([key, val]) => {
        const mainEntry: [string, string] = [key, String(val)];
        const additionalVal = additionalGroup?.[key];

        if (additionalVal != null && typeof additionalVal === 'object' && !Array.isArray(additionalVal)) {
          const additionalEntries = Object.entries(additionalVal as Record<string, unknown>).map(
            ([subKey, subVal]) => [subKey, String(subVal)] as [string, string],
          );
          return [mainEntry, ...additionalEntries];
        }

        return [mainEntry];
      });
    }

    return { title: groupKey, entries };
  });
};
import { ColDef } from 'ag-grid-community';

export const STATUS_COLUMN_WIDTH = 40;
export const RUN_INDEX_COLUMN_WIDTH = 116;
export const TURN_INDEX_COLUMN_WIDTH = 52;
export const TOTAL_TURNS_COLUMN_WIDTH = 96;
export const REQUEST_INDEX_COLUMN_WIDTH = 52;
export const TOTAL_REQUESTS_COLUMN_WIDTH = 96;
export const TEST_CASE_NAME_COLUMN_WIDTH = 156;
export const HTTP_COLUMN_WIDTH = 62;
export const DURATION_COLUMN_WIDTH = 100;
export const EXTRACTED_COLUMN_MIN_WIDTH = 120;
export const METRIC_COLUMN_WIDTH = 148;

export const TEXT_FILTER_COL_DEF: Pick<ColDef, 'filter' | 'floatingFilter' | 'floatingFilterComponent'> = {
  filter: 'agTextColumnFilter',
  floatingFilter: true,
  floatingFilterComponent: 'agTextColumnFloatingFilter',
};

export const NUMBER_FILTER_COL_DEF: Pick<ColDef, 'filter' | 'floatingFilter' | 'floatingFilterComponent'> = {
  filter: 'agNumberColumnFilter',
  floatingFilter: true,
  floatingFilterComponent: 'agNumberColumnFloatingFilter',
};

export const NO_FILTER_COL_DEF: Pick<ColDef, 'filter' | 'floatingFilter'> = {
  filter: false,
  floatingFilter: false,
};

export const fixedWidthColDef = (width: number): Pick<ColDef, 'width' | 'minWidth'> => ({
  width,
  minWidth: width,
});

export const lockedWidthColDef = (width: number): Pick<ColDef, 'width' | 'minWidth' | 'maxWidth' | 'flex'> => ({
  width,
  minWidth: width,
  maxWidth: width,
  flex: 0,
});

